   const imported=document.createElement('button');imported.className='primary';imported.textContent='Import books saved on this browser';imported.disabled=!ready;imported.onclick=()=>{const data=guest(),snapshot=window.libraryBridge.get(),ids=new Set(snapshot.books.map(b=>b.id));const additions=data.books.filter(b=>!ids.has(b.id));snapshot.books.push(...additions);const known=new Set(snapshot.memories.map(m=>JSON.stringify(m)));snapshot.memories.push(...data.memories.filter(m=>!known.has(JSON.stringify(m))));window.libraryBridge.set(snapshot);window.cloudQueue();status(additions.length+' local books added to this account.');};root.append(imported);
