   const logout=document.createElement('button');logout.className='auth-secondary';logout.textContent='Sign out';logout.onclick=async()=>{await flush();if(dirty||inFlight){status('Cloud saving is pending. Keep a backup or wait before signing out.');return}const result=await client.auth.signOut();if(result.error)status(result.error.message)};root.append(logout);
