   const explanation=document.createElement('p');explanation.id='account-signin-help';explanation.className='account-signin-help';explanation.textContent=googleEnabled?'Or use an email sign-in link below. Both methods load the library belonging to your signed-in account.':'Google sign-in is awaiting setup by the site owner. Email sign-in is available below.';root.append(explanation);
   const form=document.createElement('form');form.id='email-signin-form';form.innerHTML='<label for="signin-email">Email address</label><input id="signin-email" type="email" required autocomplete="email" name="email" placeholder="you@example.com"><button class="primary" type="submit">Send sign-in email</button>';form.querySelector('input').value=email;form.querySelector('button').disabled=!configured||sending;form.onsubmit=async event=>{event.preventDefault();if(!configured||sending)return;email=form.querySelector('input').value.trim();sending=true;render();try{const result=await client.auth.signInWithOtp({email,options:{emailRedirectTo:window.location.origin+'/'}});if(result.error)throw result.error;codeSent=true;status('Check your email. Open the sign-in link or enter the email code below.')}catch(error){const limited=error.code==='over_email_send_rate_limit'||error.code==='over_email_request_rate_limit'||error.status===429||/email rate limit/i.test(error.message||'');status(limited?'Email requests are temporarily limited by the sign-in service. Wait for the limit to reset before requesting another email. If an earlier link is still valid, you can try it. The site owner can configure custom SMTP in Supabase for visitor sign-ins.':error.message||'Could not send the sign-in email. Try again.')}finally{sending=false;render()}};root.append(form);
