 async function flush(){
  clearTimeout(timer);if(inFlight)return inFlight;if(!user||!ready||!dirty||paused)return;
  const owner=user.id,token=epoch;dirty=false;status('Saving to your account…');const snapshot=window.libraryBridge.get();snapshot.books=snapshot.books.filter(b=>!b.isSample);
  inFlight=(async()=>{try{const next=(revision||0)+1,data={user_id:owner,payload:snapshot,revision:next,updated_at:new Date().toISOString()},table=client.from('diary_libraries');const result=revision===null?await table.insert(data).select('revision').single():await table.update(data).eq('user_id',owner).eq('revision',revision).select('revision').maybeSingle();if(token!==epoch)return;if(result.error||!result.data){dirty=true;paused=true;status('Cloud save paused. Another device may have changed this book. Keep a backup, then retry loading.')}else{revision=result.data.revision;put(pendingKey(owner),dirty);status(dirty?'Changes saved on this device · syncing…':'Saved to your account ✓')}}catch{if(token===epoch){dirty=true;status('Offline · changes kept on this device')}}finally{inFlight=null;if(user&&ready&&dirty&&!paused)timer=setTimeout(flush,4000)}})();return inFlight;
 }
 window.cloudQueue=()=>{if(!user||!ready)return;dirty=true;put(pendingKey(user.id),true);status('Changes saved on this device · syncing…');clearTimeout(timer);if(!paused)timer=setTimeout(flush,900)};
 function transition(session,force=false){
  const owner=session?.user?.id||null;if(!force&&owner===loadedOwner&&ready){user=session?.user||null;render();return Promise.resolve()}if(!force&&owner===loadingOwner&&loadingPromise)return loadingPromise;
  const token=++epoch;loadingOwner=owner;ready=false;user=session?.user||null;revision=null;dirty=false;paused=false;remoteConflict=null;clearTimeout(timer);window.voiceSession?.stop();notify();render();
  if(!owner){window.libraryScope=null;window.libraryBridge.set(guest());loadedOwner=null;ready=true;status(configured?'Sign in to save books to your account.':'Email sign-in is being set up. You can explore the sample for now.');render();notify();loadingOwner=undefined;return Promise.resolve()}
  if(window.libraryScope!==owner){window.libraryScope=owner;window.libraryViewOnly=true;try{window.libraryBridge.set({books:[],memories:[]})}finally{window.libraryViewOnly=false}}
  loadingPromise=(async()=>{try{const result=await client.from('diary_libraries').select('payload,revision').eq('user_id',owner).maybeSingle();if(token!==epoch)return;if(result.error)throw result.error;const cached=raw('wd-account-'+owner+'-wd-books',null),cachedMemories=raw('wd-account-'+owner+'-wd-memories',[]),localPending=raw(pendingKey(owner),false);revision=result.data?.revision??null;window.libraryScope=owner;
    if(cached&&localPending&&result.data){window.libraryBridge.set({books:cached,memories:cachedMemories});remoteConflict=result.data.payload;dirty=true;paused=true;status('Unsynced changes exist on this device. Choose which version to keep, or download a backup.')}else{window.libraryBridge.set(result.data?.payload||(cached?{books:cached,memories:cachedMemories}:{books:[],memories:[]}));dirty=!!cached&&localPending;status(result.data?'Your account books are ready.':'Your account is ready. Make your first book.');if(dirty)timer=setTimeout(flush,900)}
    loadedOwner=owner;ready=true;render();notify();if(!pendingCreate&&!raw('wd-create-after-signin',false))changeView('books');resumeCreation();
   }catch{if(token!==epoch)return;status('Could not load your account books. Your saved copies are unchanged; retry when connected.');ready=false;render();notify()}finally{if(token===epoch){loadingOwner=undefined;loadingPromise=null}}})();return loadingPromise;
 }
 async function install(sdkClient,providers={}){client=sdkClient;configured=true;googleEnabled=providers.google===true;client.auth.onAuthStateChange((_event,session)=>{setTimeout(()=>transition(session),0)});const result=await client.auth.getSession();if(result.error){status('Could not check your sign-in. Retry when connected.');render();return}await transition(result.data.session)}
