 (async()=>{try{const config=await fetch('auth-config.json',{cache:'no-store'}).then(r=>r.json());if(!config?.supabaseUrl||!config?.publishableKey){ready=true;status('Email sign-in is being set up. You can explore the sample for now.');render();notify();return}const [{createClient},providers]=await Promise.all([import('https://esm.sh/@supabase/supabase-js@2'),fetch(config.supabaseUrl+'/auth/v1/settings',{headers:{apikey:config.publishableKey}}).then(response=>response.ok?response.json():{}).then(data=>data.external||{}).catch(()=>({}))]);await install(createClient(config.supabaseUrl,config.publishableKey,{auth:{flowType:'pkce',detectSessionInUrl:true,persistSession:true}}),providers)}catch{ready=false;status('The sign-in service could not load. Refresh to try again.');render();notify()}})();
